<script>
    function toggleFaq(button) {
      const content = button.nextElementSibling;
      const arrow = button.querySelector('.icon-arrow');
      const isHidden = content.classList.contains('hidden');

      // Close all other FAQs for clean accordion behavior
      document.querySelectorAll('#faq-container .faq-content').forEach(item => {
        item.classList.add('hidden');
      });
      document.querySelectorAll('#faq-container .icon-arrow').forEach(item => {
        item.classList.remove('rotate-180');
      });

      if (isHidden) {
        content.classList.remove('hidden');
        arrow.classList.add('rotate-180');
      }
    }

    function triggerDownloadAlert(templateName) {
      // Simulate download feedback to the user
      alert('Mengunduh ' + templateName + '. Template akan otomatis terunduh dalam format standar akademik printno.id.');
    }
